import (
	"errors"
	"sync"
	"time"
)

// Clock is an interface for time sources.
type Clock interface {
	Now() time.Time
}

// TokenBucket implements a concurrency-safe token bucket rate limiter.
type TokenBucket struct {
	mu    sync.Mutex
	rate  float64 // tokens per second
	burst float64 // maximum tokens
	tokens float64
	last  time.Time
	clock Clock
}

// NewTokenBucket creates a new TokenBucket with the given rate (tokens/sec)
// and burst capacity. It validates that rate > 0, burst > 0, and clock is non-nil.
func NewTokenBucket(rate, burst float64, clock Clock) (*TokenBucket, error) {
	if rate <= 0 {
		return nil, errors.New("rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("burst must be positive")
	}
	if clock == nil {
		return nil, errors.New("clock must not be nil")
	}
	return &TokenBucket{
		rate:   rate,
		burst:  burst,
		tokens: burst, // start full
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// Allow reports whether one token is available.
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}

// AllowN reports whether n tokens are available. If n <= 0, it returns true.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	tb.last = now

	// Refill tokens based on elapsed time.
	tb.tokens += elapsed * tb.rate
	if tb.tokens > tb.burst {
		tb.tokens = tb.burst
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}
