package ratelimiter

import (
	"fmt"
	"sync"
	"time"
)

// Clock provides the current time.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token bucket rate limiter.
type Limiter struct {
	mu     sync.Mutex
	rate   float64 // tokens per second
	burst  float64 // maximum token capacity
	tokens float64 // current token count
	last   time.Time
	clock  Clock
}

// NewLimiter creates a Limiter with the given rate (tokens/sec) and burst capacity.
// It validates that rate and burst are positive, and defaults to the real clock if nil.
func NewLimiter(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, fmt.Errorf("rate must be positive")
	}
	if burst <= 0 {
		return nil, fmt.Errorf("burst must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst, // start full
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens can be taken from the bucket at the current time.
// It is safe for concurrent use.
func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.refill(now)
	if n <= int(l.tokens) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// refill adds tokens based on elapsed time since the last refill.
// The caller must hold the mutex.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
}
