}

// Allow reports whether one token can be taken.
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}

// refill adds tokens based on elapsed time, capped at burst.
func (tb *TokenBucket) refill() {
	now := tb.clock.Now()
	elapsed := now.Sub(tb.lastRefill).Seconds()
	if elapsed > 0 {
		tb.tokens = min(tb.burst, tb.tokens+elapsed*tb.rate)
		tb.lastRefill = now
	}
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
